## Section Evaluation Schema

```typescript
interface SectionEvaluation {
  section_id: string;
  section_name: string;
  score: 1 | 2 | 3 | 4 | 5;
  status: "Pass" | "Conditional" | "Fail";
  comments: string[];
  findings: Finding[];
  evidence: string[];
}

interface Finding {
  finding_id: string;
  section: string;
  severity: "critical" | "major" | "minor" | "info";
  category: "completeness" | "clarity" | "compliance" | "technical" | "structure";
  description: string;
  location: string;
  recommendation: string;
  is_mandatory: boolean;
}
```

